t.script:
(function () {
  const initWizardForms = () => {
    const forms = document.querySelectorAll('form.o_form_wizard');
    if (!forms.length) return;

    const getLabelText = (fieldEl) => {
      const labelContent = fieldEl.querySelector('.s_website_form_label_content');
      if (labelContent  && labelContent.textContent.trim()) return labelContent.textContent.trim();

      const label = fieldEl.querySelector('label');
      if (label  && label.textContent.trim()) return label.textContent.replace(/\*/g, '').trim();

      return (fieldEl.getAttribute('data-translated-name') || fieldEl.getAttribute('data-name') || 'Pergunta').trim();
    };

    const isFieldConditionallyVisible = (fieldEl) => {
      if (!fieldEl) return false;

      const hiddenClassList = [
        'd-none',
        'o_invisible_modifier',
        'o_snippet_invisible',
        'o_hidden',
        'visually-hidden',
      ];

      let cur = fieldEl;
      while (cur  && cur !== document.documentElement) {
        if (cur.classList  && cur.classList.contains('o_form_wizard_q')) break;

        if (cur.hidden) return false;
        if (cur.getAttribute  && cur.getAttribute('aria-hidden') === 'true') return false;

        if (cur.classList) {
          for (const c of hiddenClassList) {
            if (cur.classList.contains(c)) return false;
          }
        }

        if (cur.style  && cur.style.display === 'none') return false;

        cur = cur.parentElement;
      }
      return true;
    };

    const isStepConditionallyVisible = (stepEl) => {
      const fieldEl = stepEl.querySelector('.s_website_form_field');
      return isFieldConditionallyVisible(fieldEl);
    };

    const isStepAnswered = (stepEl) => {
      if (!isStepConditionallyVisible(stepEl)) return true;

      const fields = stepEl.querySelectorAll('input, select, textarea');
      if (!fields.length) return true;

      const checkboxes = stepEl.querySelectorAll('input[type="checkbox"]');
      if (checkboxes.length) return Array.from(checkboxes).some(c => c.checked);

      const field = fields[0];
      if (typeof field.checkValidity === 'function') return field.checkValidity();
      return (field.value || '').trim().length > 0;
    };

    const focusFirstField = (stepEl) => {
      const field = stepEl.querySelector('input:not([type="hidden"]), textarea, select');
      if (field) field.focus({ preventScroll: true });
    };

    const showStepWithFade = (steps, nextIndex, currentIndex) => {
      const currentStep = steps[currentIndex];
      const nextStep = steps[nextIndex];

      if (currentStep) currentStep.classList.remove('is-visible');

      window.setTimeout(() => {
        steps.forEach((s, i) => s.classList.toggle('is-active', i === nextIndex));
        void nextStep.offsetWidth;
        nextStep.classList.add('is-visible');
        focusFirstField(nextStep);
      }, 180);
    };

    const safeSubmit = (form) => {
      // Prefer Odoo's handler (usually bound to this button)
      const odooSend = form.querySelector('a.s_website_form_send, button.s_website_form_send, input.s_website_form_send');
      if (odooSend) return odooSend.click();

      if (typeof form.requestSubmit === 'function') return form.requestSubmit();

      const realSubmit = form.querySelector('button[type="submit"], input[type="submit"]');
      if (realSubmit) return realSubmit.click();

      form.submit();
    };

    forms.forEach((form) => {
      // If already ready, skip
      if (form.dataset.wizardReady === '1') return;

      const rows = form.querySelector('.s_website_form_rows');
      if (!rows) return;

      // Ensure wrap/card exist (or reuse existing)
      let card = rows.closest('.o_form_wizard_card');
      if (!card) {
        const wrap = document.createElement('div');
        wrap.className = 'o_form_wizard_wrap';

        card = document.createElement('div');
        card.className = 'o_form_wizard_card';

        wrap.appendChild(card);
        rows.parentNode.insertBefore(wrap, rows);
        card.appendChild(rows);
      }

      // Steps: reuse existing wizard steps if present, otherwise build them
      let steps = Array.from(rows.querySelectorAll(':scope > .o_form_wizard_q'));

      if (steps.length) {
        // sort by data-step-index if present
        steps.sort((a, b) => {
          const ai = parseInt(a.dataset.stepIndex || '0', 10);
          const bi = parseInt(b.dataset.stepIndex || '0', 10);
          return ai - bi;
        });
      } else {
        const fieldEls = Array.from(rows.children).filter(el =>
          el.classList.contains('s_website_form_field')  &&
          !el.classList.contains('s_website_form_field_hidden')
        );

        if (fieldEls.length <= 1) return;

        steps = fieldEls.map((fieldEl, idx) => {
          const step = document.createElement('div');
          step.className = 'o_form_wizard_q';
          step.dataset.stepIndex = String(idx);

          const title = document.createElement('div');
          title.className = 'o_form_wizard_title';
          title.textContent = getLabelText(fieldEl);

          step.appendChild(title);
          step.appendChild(fieldEl);

          rows.insertBefore(step, rows.firstChild);
          return step;
        });

        steps.sort((a, b) => parseInt(a.dataset.stepIndex, 10) - parseInt(b.dataset.stepIndex, 10));
      }

      // Ensure each step has a title
      steps.forEach((stepEl) => {
        if (stepEl.querySelector('.o_form_wizard_title')) return;
        const fieldEl = stepEl.querySelector('.s_website_form_field');
        if (!fieldEl) return;

        const title = document.createElement('div');
        title.className = 'o_form_wizard_title';
        title.textContent = getLabelText(fieldEl);
        stepEl.insertBefore(title, stepEl.firstChild);
      });

      // Find submit row (might not be inside steps)
      const submitRow = rows.querySelector('.s_website_form_submit') || form.querySelector('.s_website_form_submit');

      // Ensure nav exists
      let nav = card.querySelector('.o_form_wizard_nav');
      if (!nav) {
        nav = document.createElement('div');
        nav.className = 'o_form_wizard_nav';
        nav.innerHTML = `
          ↑
          ↓
        `;
        card.appendChild(nav);
      }

      // Remove old listeners safely by cloning
      const navClone = nav.cloneNode(true);
      nav.parentNode.replaceChild(navClone, nav);
      nav = navClone;

      let current = 0;

      const getNextVisibleIndex = (from, dir) => {
        let i = from;
        while (true) {
          i += dir;
          if (i < 0 || i >= steps.length) return null;
          if (isStepConditionallyVisible(steps[i])) return i;
        }
      };

      const getFirstVisibleIndex = () => {
        for (let i = 0; i < steps.length; i++) {
          if (isStepConditionallyVisible(steps[i])) return i;
        }
        return 0;
      };

      const ensureCurrentIsVisible = () => {
        if (isStepConditionallyVisible(steps[current])) return;

        const next = getNextVisibleIndex(current, +1);
        if (next !== null) { current = next; return; }

        const prev = getNextVisibleIndex(current, -1);
        if (prev !== null) { current = prev; return; }

        current = getFirstVisibleIndex();
      };

      const renderNav = () => {
        ensureCurrentIsVisible();

        const prevBtn = nav.querySelector('.js_prev');
        const nextBtn = nav.querySelector('.js_next');

        prevBtn.classList.toggle('is-disabled', getNextVisibleIndex(current, -1) === null);

        const isLastVisible = (getNextVisibleIndex(current, +1) === null);
        if (submitRow) submitRow.style.display = isLastVisible ? '' : 'none';

        nextBtn.textContent = isLastVisible ? 'Submeter' : '↓';
        nextBtn.classList.toggle('o_form_wizard_ok', isLastVisible);
      };

      const renderStep = (initial = false) => {
        ensureCurrentIsVisible();
        steps.forEach((s, i) => {
          s.classList.toggle('is-active', i === current);
          if (i !== current) s.classList.remove('is-visible');
        });

        if (initial) {
          window.setTimeout(() => steps[current].classList.add('is-visible'), 0);
        } else {
          steps[current].classList.add('is-visible');
        }

        focusFirstField(steps[current]);
        renderNav();
      };

      const goNext = () => {
        ensureCurrentIsVisible();

        const stepEl = steps[current];
        if (!isStepAnswered(stepEl)) {
          const firstField = stepEl.querySelector('input, textarea, select');
          if (firstField  && typeof firstField.reportValidity === 'function') firstField.reportValidity();
          return;
        }

        const next = getNextVisibleIndex(current, +1);
        if (next !== null) {
          const old = current;
          current = next;
          showStepWithFade(steps, current, old);
          renderNav();
          return;
        }

        safeSubmit(form);
      };

      const goPrev = () => {
        ensureCurrentIsVisible();
        const prev = getNextVisibleIndex(current, -1);
        if (prev === null) return;

        const old = current;
        current = prev;
        showStepWithFade(steps, current, old);
        renderNav();
      };

      nav.querySelector('.js_next').addEventListener('click', goNext);
      nav.querySelector('.js_prev').addEventListener('click', goPrev);

      form.addEventListener('keydown', (e) => {
        if (e.key !== 'Enter') return;
        const activeStep = steps[current];
        if (activeStep  && activeStep.querySelector('textarea:focus')) return;
        e.preventDefault();
        goNext();
      });

      // Observe changes that might toggle visibility classes
      const mo = new MutationObserver(() => {
        const was = current;
        ensureCurrentIsVisible();
        if (current !== was) showStepWithFade(steps, current, was);
        renderNav();
      });

      mo.observe(form, {
        attributes: true,
        subtree: true,
        attributeFilter: ['class', 'style', 'hidden', 'aria-hidden']
      });

      // Mark as ready (this enables wizard-only CSS)
      form.dataset.wizardReady = '1';

      // Init
      current = getFirstVisibleIndex();
      renderStep(true);
    });
  };

  const boot = () => {
    initWizardForms();

    // Re-init when Studio/editor alters the DOM (sections removed/added)
    const root = document.getElementById('wrap') || document.body;
    const domObserver = new MutationObserver(() => initWizardForms());
    domObserver.observe(root, { childList: true, subtree: true });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();

document.addEventListener('DOMContentLoaded', () => {
  // Find newsletter forms in this page (mailing.contact)
  const forms = Array.from(document.querySelectorAll('form[data-model_name="mailing.contact"]'));
  if (!forms.length) return;

  const getLabelText = (fieldEl) => {
    const labelContent = fieldEl.querySelector('.s_website_form_label_content');
    if (labelContent && labelContent.textContent.trim()) return labelContent.textContent.trim();
    const label = fieldEl.querySelector('label');
    if (label && label.textContent.trim()) return label.textContent.replace(/\*/g, '').trim();
    return (fieldEl.getAttribute('data-translated-name') || fieldEl.getAttribute('data-name') || 'Pergunta').trim();
  };

  const focusFirstField = (stepEl) => {
    const field = stepEl.querySelector('input:not([type="hidden"]), textarea, select');
    if (field) field.focus({ preventScroll: true });
  };

  const safeSubmit = (form) => {
    // Prefer Odoo's handler (usually bound to this button)
    const odooSend = form.querySelector('a.s_website_form_send, button.s_website_form_send, input.s_website_form_send');
    if (odooSend) return odooSend.click();

    // Fallbacks
    if (typeof form.requestSubmit === 'function') return form.requestSubmit();
    const realSubmit = form.querySelector('button[type="submit"], input[type="submit"]');
    if (realSubmit) return realSubmit.click();

    form.submit();
  };

  forms.forEach((form) => {
    // If Studio saved the init flag, do NOT bail out. We'll recover and bind safely.
    const host = form.closest('.s_website_form') || form.parentElement;
    if (!host) return;

    // If wrapper already exists (saved in HTML), bind to it
    let wrap = host.querySelector(':scope > .newsletter_wizard_wrap');
    let openBtn, panel, card, closeBtn;

    // capture success message BEFORE moving (or if already moved, just find it)
    let endMsg = host.querySelector('.s_website_form_end_message');

    if (!wrap) {
      // Hide the form initially (we'll put it in a panel)
      form.style.display = 'none';

      wrap = document.createElement('div');
      wrap.className = 'newsletter_wizard_wrap';

      openBtn = document.createElement('button');
      openBtn.type = 'button';
      openBtn.className = 'newsletter_wizard_btn';
      openBtn.textContent = 'Subscrever';

      panel = document.createElement('div');
      panel.className = 'newsletter_wizard_panel';

      card = document.createElement('div');
      card.className = 'newsletter_wizard_card';

      closeBtn = document.createElement('button');
      closeBtn.type = 'button';
      closeBtn.className = 'newsletter_wizard_close';
      closeBtn.setAttribute('aria-label', 'Fechar');
      closeBtn.textContent = '✕';

      panel.appendChild(card);
      wrap.appendChild(openBtn);
      wrap.appendChild(panel);

      // insert wrapper before the form host content
      host.insertBefore(wrap, host.firstChild);

      // Move the form into the card
      card.appendChild(closeBtn);
      card.appendChild(form);

      // Move success message into the card too
      if (endMsg) card.appendChild(endMsg);

      form.style.display = ''; // visible inside panel (panel still hidden)
    } else {
      openBtn = wrap.querySelector('.newsletter_wizard_btn');
      panel = wrap.querySelector('.newsletter_wizard_panel');
      card = wrap.querySelector('.newsletter_wizard_card');
      closeBtn = wrap.querySelector('.newsletter_wizard_close');

      // If structure is partially missing, rebuild minimal missing pieces
      if (!panel) {
        panel = document.createElement('div');
        panel.className = 'newsletter_wizard_panel';
        wrap.appendChild(panel);
      }
      if (!card) {
        card = document.createElement('div');
        card.className = 'newsletter_wizard_card';
        panel.appendChild(card);
      }
      if (!openBtn) {
        openBtn = document.createElement('button');
        openBtn.type = 'button';
        openBtn.className = 'newsletter_wizard_btn';
        openBtn.textContent = 'Subscrever';
        wrap.insertBefore(openBtn, panel);
      }
      if (!closeBtn) {
        closeBtn = document.createElement('button');
        closeBtn.type = 'button';
        closeBtn.className = 'newsletter_wizard_close';
        closeBtn.setAttribute('aria-label', 'Fechar');
        closeBtn.textContent = '✕';
        card.insertBefore(closeBtn, card.firstChild);
      }

      // Ensure form is inside card
      if (!card.contains(form)) card.appendChild(form);
      if (endMsg && !card.contains(endMsg)) card.appendChild(endMsg);
    }

    // Prevent double-binding listeners by replacing controls (safe rebinding)
    const openBtnNew = openBtn.cloneNode(true);
    openBtn.parentNode.replaceChild(openBtnNew, openBtn);
    openBtn = openBtnNew;

    const closeBtnNew = closeBtn.cloneNode(true);
    closeBtn.parentNode.replaceChild(closeBtnNew, closeBtn);
    closeBtn = closeBtnNew;

    // Build steps (only from visible fields, excluding hidden list_ids)
    const rows = form.querySelector('.s_website_form_rows');
    if (!rows) return;

    // Reuse existing steps if present
    let steps = Array.from(rows.querySelectorAll(':scope > .o_form_wizard_q'));

    if (!steps.length) {
      const fieldEls = Array.from(rows.children).filter(el =>
        el.classList.contains('s_website_form_field') &&
        !el.classList.contains('s_website_form_field_hidden')
      );

      if (fieldEls.length <= 1) {
        openBtn.addEventListener('click', () => {
          panel.classList.add('is-open');
          openBtn.style.display = 'none';
        });
        closeBtn.addEventListener('click', () => {
          panel.classList.remove('is-open');
          openBtn.style.display = '';
        });
        return;
      }

      steps = fieldEls.map((fieldEl, idx) => {
        const step = document.createElement('div');
        step.className = 'o_form_wizard_q';
        step.dataset.stepIndex = String(idx);

        const title = document.createElement('div');
        title.className = 'o_form_wizard_title';
        title.textContent = getLabelText(fieldEl);

        step.appendChild(title);
        step.appendChild(fieldEl);

        rows.insertBefore(step, rows.firstChild);
        return step;
      });

      // restore order
      steps = steps
        .slice()
        .sort((a,b) => parseInt(a.dataset.stepIndex || '0',10) - parseInt(b.dataset.stepIndex || '0',10));
    }

    const submitRow = rows.querySelector('.s_website_form_submit') || form.querySelector('.s_website_form_submit');

    // If Studio saved steps out of order, normalize by step index.
    if (steps.length > 1) {
      const sorted = steps.slice().sort((a, b) =>
        parseInt(a.dataset.stepIndex || '0', 10) - parseInt(b.dataset.stepIndex || '0', 10)
      );
      const anchor = (submitRow && submitRow.parentElement === rows) ? submitRow : null;
      sorted.forEach((s) => rows.insertBefore(s, anchor));
      steps = sorted;
    }

    // Ensure nav exists
    let nav = card.querySelector(':scope > .o_form_wizard_nav');
    if (!nav) {
      nav = document.createElement('div');
      nav.className = 'o_form_wizard_nav';
      nav.innerHTML = `
        ↑
        ↓
      `;
      card.appendChild(nav);
    } else {
      if (!nav.querySelector('.js_prev') || !nav.querySelector('.js_next')) {
        nav.innerHTML = `
          ↑
          ↓
        `;
      }
    }

    // Replace nav buttons to remove any old handlers
    const prevOld = nav.querySelector('.js_prev');
    const nextOld = nav.querySelector('.js_next');
    const prevBtn = prevOld.cloneNode(true);
    const nextBtn = nextOld.cloneNode(true);
    prevOld.parentNode.replaceChild(prevBtn, prevOld);
    nextOld.parentNode.replaceChild(nextBtn, nextOld);

    let current = 0;

    const isStepAnswered = (stepEl) => {
      const fields = stepEl.querySelectorAll('input, select, textarea');
      if (!fields.length) return true;

      const checkboxes = stepEl.querySelectorAll('input[type="checkbox"]');
      if (checkboxes.length) return Array.from(checkboxes).some(c => c.checked);

      const field = fields[0];
      if (typeof field.checkValidity === 'function') return field.checkValidity();
      return (field.value || '').trim().length > 0;
    };

    const renderNav = () => {
      prevBtn.classList.toggle('is-disabled', current === 0);

      const isLast = current === (steps.length - 1);

      // show/hide default Odoo submit row only on last step
      if (submitRow) submitRow.style.display = isLast ? 'block' : 'none';

      nextBtn.textContent = isLast ? 'Submeter' : '↓';
      nextBtn.classList.toggle('o_form_wizard_ok', isLast);
    };

    const renderStep = (initial=false) => {
      steps.forEach((s,i) => {
        s.classList.toggle('is-active', i === current);
        if (i !== current) s.classList.remove('is-visible');
      });

      if (initial) setTimeout(() => steps[current].classList.add('is-visible'), 0);
      else steps[current].classList.add('is-visible');

      focusFirstField(steps[current]);
      renderNav();
    };

    const goNext = () => {
      const stepEl = steps[current];
      if (!isStepAnswered(stepEl)) {
        const firstField = stepEl.querySelector('input, textarea, select');
        if (firstField && typeof firstField.reportValidity === 'function') firstField.reportValidity();
        return;
      }

      const isLast = current === (steps.length - 1);
      if (!isLast) {
        const old = current;
        current += 1;
        steps[old].classList.remove('is-visible');
        setTimeout(() => {
          steps.forEach((s,i) => s.classList.toggle('is-active', i === current));
          void steps[current].offsetWidth;
          steps[current].classList.add('is-visible');
          focusFirstField(steps[current]);
          renderNav();
        }, 160);
        return;
      }

      safeSubmit(form);
    };

    const goPrev = () => {
      if (current === 0) return;
      const old = current;
      current -= 1;
      steps[old].classList.remove('is-visible');
      setTimeout(() => {
        steps.forEach((s,i) => s.classList.toggle('is-active', i === current));
        void steps[current].offsetWidth;
        steps[current].classList.add('is-visible');
        focusFirstField(steps[current]);
        renderNav();
      }, 160);
    };

    nextBtn.addEventListener('click', goNext);
    prevBtn.addEventListener('click', goPrev);

    form.addEventListener('keydown', (e) => {
      if (e.key !== 'Enter') return;
      const activeStep = steps[current];
      if (activeStep && activeStep.querySelector('textarea:focus')) return;
      e.preventDefault();
      goNext();
    });

    // Open/close behavior
    openBtn.addEventListener('click', () => {
      panel.classList.add('is-open');
      openBtn.style.display = 'none'; // hide after click
      current = 0;
      renderStep(true);
    });

    const closePanel = () => {
      panel.classList.remove('is-open');
      openBtn.style.display = ''; // show button again
    };

    closeBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      closePanel();
    });

    // Init in closed state
    renderStep(true);
  });
});

div.script:
document.addEventListener('DOMContentLoaded', function () {
    const toggleBtn = document.getElementById('project3d-form-toggle');
    const formPanel = document.getElementById('project3d-form-panel');

    if (!toggleBtn || !formPanel) {
        return;
    }

    formPanel.classList.add('d-none');

    const toggleVisibility = (event) => {
        event.preventDefault();
        formPanel.classList.toggle('d-none');
        if (!formPanel.classList.contains('d-none')) {
            const form = formPanel.querySelector('form.o_form_wizard');
            if (form) {
                form.dispatchEvent(new Event('o-wizard-reset'));
            }
            formPanel.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    };

    toggleBtn.addEventListener('click', toggleVisibility);
});
